from collections import deque,Counter
R=C=30
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if rows[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and rows[nx][ny] and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   comps.append(cells)
[(len(x),Counter(rows[r][c] for r,c in x), (min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps]

# label components and map marker colors
label={}; compcolor={}
for i,cells in enumerate(comps):
 for p in cells: label[p]=i
 colors={rows[r][c] for r,c in cells if rows[r][c]>1}
 compcolor[i]=next(iter(colors)) if colors else None
out=[row[:] for row in rows]
for r in range(1,29):
 for c in range(1,29):
  if all(rows[x][y]!=0 for x in range(r-1,r+2) for y in range(c-1,c+2)):
   i=label[(r,c)]
   if compcolor[i] is not None and rows[r][c]==1:
    out[r][c]=compcolor[i]
print('\n'.join(' '.join(map(str,row)) for row in out))
